import { Link, useNavigate } from "react-router-dom";

export const HomePage = () => {
  const navigate = useNavigate();

  const handleNavigate = () => {
    navigate("/products");
  };
  return (
    <>
      <h1>My Home Page</h1>
      <p>
        Go to <Link to={"/products"}>the list of products.</Link>
      </p>
      <button onClick={handleNavigate}></button>
    </>
  );
};
